typedef float rational_t;
typedef float time_value_t;

class string_buf
{
public:
  bool is_equal(const string_buf& other) const;
};

class stringx
{
  char* chars;
  string_buf* my_buf;
public:
  friend inline bool operator==(const stringx& lhs, const stringx& rhs);
  friend inline bool operator!=(const stringx& lhs, const stringx& rhs);
};

inline bool operator==(const stringx& lhs, const stringx& rhs)
{
  return lhs.my_buf->is_equal(*rhs.my_buf);
}

inline bool operator!=(const stringx& lhs, const stringx& rhs)
{
  return !(lhs == rhs);
}

extern stringx empty_string;
class entity;

class generic_interface
{
public:
  virtual ~generic_interface();
};

class entity_interface : public generic_interface
{
protected:
  entity *my_entity;
public:
  entity *get_my_entity() const { return(my_entity); }
};

class animation_interface : public entity_interface
{
public:
  enum
  {
    ANIM_IFC_REVERSE = 0x00000001
  };

  const stringx& extract_random_anim_info_id_map_anim(const stringx& id, int *damage_value = 0, rational_t *recover = 0, rational_t *recover_var = 0, int *flags = 0);
};

class entity
{
  animation_interface *my_animation_interface;
public:
  bool has_animation_ifc() const { return (my_animation_interface != 0); }
  animation_interface *animation_ifc() const { return my_animation_interface; }
  void *play_anim(int slot, const stringx& filename, time_value_t start_time, unsigned short anim_flags = 0, short loop = -1);
  void kill_anim(int slot);
};

enum anim_flags_t
{
  ANIM_REVERSE = 0x0002
};

class ai_interface : public entity_interface
{
public:
  bool play_animation(const stringx &anim_id, int slot, unsigned short anim_flags, int *damage_value, rational_t *recover, rational_t *recover_var, int *flags);
};

bool ai_interface::play_animation(const stringx &anim_id, int slot, unsigned short anim_flags, int *damage_value, rational_t *recover, rational_t *recover_var, int *flags)
{
  if(my_entity->has_animation_ifc())
  {
    int my_flags;
    const stringx &res = my_entity->animation_ifc()->extract_random_anim_info_id_map_anim(anim_id, damage_value, recover, recover_var, &my_flags);
    if(flags)
      *flags = my_flags;


    if( res != empty_string )
    {
      if(my_flags & animation_interface::ANIM_IFC_REVERSE)
        anim_flags |= ANIM_REVERSE;

      get_my_entity()->play_anim( slot, res, 0.0f, anim_flags);
      return(true);
    }
    else
    {
      get_my_entity()->kill_anim( slot );
      return(false);
    }
  }

  return(false);
}
